/* DPCT_ORIG   template< class T, class R, unsigned int D > __inline__ __host__ __device__
  vector_td<typename vectorTDReturnType<T,R>::type,D> operator+ ( const vector_td<T,D> &v1, const vector_td<R,D> &v2 )*/
