  template <class T, unsigned int D> __inline__ bool operator!=(const vector_td<T, D>& v1, const vector_td<T, D>& v2)
  { 
    for(unsigned int i=0; i<D; i++ ) if((v1.vec[i] != v2.vec[i])) return true;
    return false;
  }

