// kernel main
//

/* DPCT_ORIG template<class T, unsigned int D, template<class, unsigned int> class K>
__global__ void
NFFT_H_atomic_convolve_kernel(vector_td<unsigned int, D> matrix_size_os, vector_td<unsigned int, D> matrix_size_wrap,
                               unsigned int num_samples_per_frame, unsigned int num_batches,
                               const vector_td<realType_t<T>,D> * __restrict__ traj_positions, const T * __restrict__
samples, T * __restrict__ image, const ConvolutionKernel<realType_t<T>, D, K>* kernel)*/
template <class T, unsigned int D, template <class, unsigned int> class K>
/*
DPCT1110:4: The total declared local variable size in device function NFFT_H_atomic_convolve_kernel exceeds 128 bytes
and may cause high register pressure. Consult with your hardware vendor to find the total register size available and
adjust the code, or use smaller sub-group size to avoid high register pressure.
*/
void NFFT_H_atomic_convolve_kernel(vector_td<unsigned int, D> matrix_size_os,
                                   vector_td<unsigned int, D> matrix_size_wrap, unsigned int num_samples_per_frame,
                                   unsigned int num_batches,
                                   const vector_td<realType_t<T>, D>* __restrict__ traj_positions,
                                   const T* __restrict__ samples, T* __restrict__ image,
                                   const ConvolutionKernel<realType_t<T>, D, K>* kernel)
{
/* DPCT_ORIG     const unsigned int sample_idx_in_frame = (blockIdx.x * blockDim.x + threadIdx.x);*/
    auto item_ct1 = sycl::ext::oneapi::this_work_item::get_nd_item<3>();
    const unsigned int sample_idx_in_frame =
        (item_ct1.get_group(2) * item_ct1.get_local_range(2) + item_ct1.get_local_id(2));

    // Check if we are within bounds
    if( sample_idx_in_frame >= num_samples_per_frame )
      return;

/* DPCT_ORIG     const unsigned int frame = blockIdx.y;*/
    const unsigned int frame = item_ct1.get_group(1);
/* DPCT_ORIG     const unsigned int num_frames = gridDim.y;*/
    const unsigned int num_frames = item_ct1.get_group_range(1);
    const unsigned int num_samples_per_batch = num_samples_per_frame*num_frames ;
    const unsigned int sample_idx_in_batch = sample_idx_in_frame+frame*num_samples_per_frame;
    
    // Sample position computed in preprocessing includes a wrap zone. Remove this wrapping.
    const vector_td<realType_t<T>,D> half_wrap_real =
        vector_td<realType_t<T>,D>(matrix_size_wrap>>1);
    const vector_td<realType_t<T>,D> sample_position =
        traj_positions[sample_idx_in_batch]-half_wrap_real;
    
    // Half the kernel width
    const vector_td<realType_t<T>,D> radius_vec(kernel->get_radius());
    
    // Limits of the subgrid to consider
    const vector_td<int, D> lower_limit(ceil(sample_position - radius_vec));
    const vector_td<int, D> upper_limit(floor(sample_position + radius_vec));

    // Output to the grid.
    NFFT_iterate<T>(matrix_size_os, num_batches, samples, image,
            frame, num_frames, num_samples_per_batch, sample_idx_in_batch, 
            sample_position, lower_limit, upper_limit, kernel);
}
