/*
  CUDA implementation of the NFFT.

  -----------

  Accelerating the Non-equispaced Fast Fourier Transform on Commodity Graphics Hardware.
  T.S. Sørensen, T. Schaeffter, K.Ø. Noe, M.S. Hansen. 
  IEEE Transactions on Medical Imaging 2008; 27(4):538-547.

  Real-time Reconstruction of Sensitivity Encoded Radial Magnetic Resonance Imaging Using a Graphics Processing Unit.
  T.S. Sørensen, D. Atkinson, T. Schaeffter, M.S. Hansen.
  IEEE Transactions on Medical Imaging 2009; 28(12): 1974-1985. 
*/



//
// NFFT_H preprocessing kernels
//

// convert input trajectory in [-1/2;1/2] to [0;matrix_size_os+matrix_size_wrap]

template<class REAL, unsigned int D> struct trajectory_scale
{
    typename reald<REAL,D>::Type matrix, bias;
    
    trajectory_scale( const typename reald<REAL,D>::Type &m, const typename reald<REAL,D>::Type &b )
    {
        matrix = m;
        bias = b;
    }

/* DPCT_ORIG     __host__ __device__
    typename reald<REAL,D>::Type operator()(const typename reald<REAL,D>::Type &in) const { */

    typename reald<REAL,D>::Type operator()(const typename reald<REAL,D>::Type &in) const { 
        return component_wise_mul<REAL,D>(in,matrix)+bias;
    }
};

template<class REAL, unsigned int D>
struct compute_num_cells_per_sample
{
/* DPCT_ORIG     __host__ __device__
    compute_num_cells_per_sample(REAL _half_W) : half_W(_half_W) {}*/

    compute_num_cells_per_sample(REAL _half_W) : half_W(_half_W) {}

/* DPCT_ORIG     __host__ __device__
    unsigned int operator()(typename reald<REAL,D>::Type p) const*/

    unsigned int operator()(typename reald<REAL,D>::Type p) const
    {
        unsigned int num_cells = 1;
        for( unsigned int dim=0; dim<D; dim++ ){
/* DPCT_ORIG             unsigned int upper_limit = (unsigned int)floor((((float*)&p)[dim])+half_W);*/
            unsigned int upper_limit = (unsigned int)sycl::floor((((float*)&p)[dim]) + half_W);
            unsigned int lower_limit = (unsigned int)ceil((((float*)&p)[dim])-half_W);
            num_cells *= (upper_limit-lower_limit+1);
        }
        return num_cells;
    }
  
    REAL half_W;
};

/* DPCT_ORIG template<class REAL> __inline__ __device__ void
output_pairs( unsigned int sample_idx, unsigned int frame,
              typename reald<REAL,1>::Type &p, typename uintd<1>::Type &matrix_size_os, typename uintd<1>::Type
&matrix_size_wrap, REAL half_W, const unsigned int * __restrict__ write_offsets, unsigned int * __restrict__
tuples_first, unsigned int * __restrict__ tuples_last )*/
template <class REAL>
__inline__ void output_pairs(unsigned int sample_idx, unsigned int frame, typename reald<REAL, 1>::Type& p,
                             typename uintd<1>::Type& matrix_size_os, typename uintd<1>::Type& matrix_size_wrap,
                             REAL half_W, const unsigned int* __restrict__ write_offsets,
                             unsigned int* __restrict__ tuples_first, unsigned int* __restrict__ tuples_last)
{
/* DPCT_ORIG     unsigned int lower_limit_x = (unsigned int)ceil(p.vec[0]-half_W);*/
    unsigned int lower_limit_x = (unsigned int)sycl::ceil(p.vec[0] - half_W);
/* DPCT_ORIG     unsigned int upper_limit_x = (unsigned int)floor(p.vec[0]+half_W);*/
    unsigned int upper_limit_x = (unsigned int)sycl::floor(p.vec[0] + half_W);

    unsigned int pair_idx = 0;
    unsigned int write_offset = (sample_idx==0) ? 0 : write_offsets[sample_idx-1];
    unsigned int frame_offset = frame*prod(matrix_size_os+matrix_size_wrap);
    for( unsigned int x=lower_limit_x; x<=upper_limit_x; x++ ){
        typename uintd<1>::Type co; co.vec[0] = x;
        tuples_first[write_offset+pair_idx] = co_to_idx(co, matrix_size_os+matrix_size_wrap)+frame_offset;
        tuples_last[write_offset+pair_idx] = sample_idx;
        pair_idx++;
    }
}

/* DPCT_ORIG template<class REAL> __inline__ __device__ void
output_pairs( unsigned int sample_idx, unsigned int frame,
              typename reald<REAL,2>::Type &p, typename uintd<2>::Type &matrix_size_os, typename uintd<2>::Type
&matrix_size_wrap, REAL half_W, const unsigned int * __restrict__ write_offsets, unsigned int * __restrict__
tuples_first, unsigned int * __restrict__ tuples_last )*/
template <class REAL>
__inline__ void output_pairs(unsigned int sample_idx, unsigned int frame, typename reald<REAL, 2>::Type& p,
                             typename uintd<2>::Type& matrix_size_os, typename uintd<2>::Type& matrix_size_wrap,
                             REAL half_W, const unsigned int* __restrict__ write_offsets,
                             unsigned int* __restrict__ tuples_first, unsigned int* __restrict__ tuples_last)
{
/* DPCT_ORIG     unsigned int lower_limit_x = (unsigned int)ceil(p.vec[0]-half_W);*/
    unsigned int lower_limit_x = (unsigned int)sycl::ceil(p.vec[0] - half_W);
/* DPCT_ORIG     unsigned int lower_limit_y = (unsigned int)ceil(p.vec[1]-half_W);*/
    unsigned int lower_limit_y = (unsigned int)sycl::ceil(p.vec[1] - half_W);
/* DPCT_ORIG     unsigned int upper_limit_x = (unsigned int)floor(p.vec[0]+half_W);*/
    unsigned int upper_limit_x = (unsigned int)sycl::floor(p.vec[0] + half_W);
/* DPCT_ORIG     unsigned int upper_limit_y = (unsigned int)floor(p.vec[1]+half_W);*/
    unsigned int upper_limit_y = (unsigned int)sycl::floor(p.vec[1] + half_W);

    unsigned int pair_idx = 0;
    unsigned int write_offset = (sample_idx==0) ? 0 : write_offsets[sample_idx-1];
    unsigned int frame_offset = frame*prod(matrix_size_os+matrix_size_wrap);
    for( unsigned int y=lower_limit_y; y<=upper_limit_y; y++ ){
        for( unsigned int x=lower_limit_x; x<=upper_limit_x; x++ ){
            typename uintd<2>::Type co; co.vec[0] = x; co.vec[1] = y;
            tuples_first[write_offset+pair_idx] = co_to_idx(co, matrix_size_os+matrix_size_wrap)+frame_offset;
            tuples_last[write_offset+pair_idx] = sample_idx;
            pair_idx++;
        }
    }
}

/* DPCT_ORIG template <class REAL> __inline__ __device__ void
output_pairs( unsigned int sample_idx, unsigned int frame,
              typename reald<REAL,3>::Type &p, typename uintd<3>::Type &matrix_size_os, typename uintd<3>::Type
&matrix_size_wrap, REAL half_W, const unsigned int * __restrict__ write_offsets, unsigned int * __restrict__
tuples_first, unsigned int * __restrict__ tuples_last )*/
template <class REAL>
__inline__ void output_pairs(unsigned int sample_idx, unsigned int frame, typename reald<REAL, 3>::Type& p,
                             typename uintd<3>::Type& matrix_size_os, typename uintd<3>::Type& matrix_size_wrap,
                             REAL half_W, const unsigned int* __restrict__ write_offsets,
                             unsigned int* __restrict__ tuples_first, unsigned int* __restrict__ tuples_last)
{
/* DPCT_ORIG     unsigned int lower_limit_x = (unsigned int)ceil(p.vec[0]-half_W);*/
    unsigned int lower_limit_x = (unsigned int)sycl::ceil(p.vec[0] - half_W);
/* DPCT_ORIG     unsigned int lower_limit_y = (unsigned int)ceil(p.vec[1]-half_W);*/
    unsigned int lower_limit_y = (unsigned int)sycl::ceil(p.vec[1] - half_W);
/* DPCT_ORIG     unsigned int lower_limit_z = (unsigned int)ceil(p.vec[2]-half_W);*/
    unsigned int lower_limit_z = (unsigned int)sycl::ceil(p.vec[2] - half_W);
/* DPCT_ORIG     unsigned int upper_limit_x = (unsigned int)floor(p.vec[0]+half_W);*/
    unsigned int upper_limit_x = (unsigned int)sycl::floor(p.vec[0] + half_W);
/* DPCT_ORIG     unsigned int upper_limit_y = (unsigned int)floor(p.vec[1]+half_W);*/
    unsigned int upper_limit_y = (unsigned int)sycl::floor(p.vec[1] + half_W);
/* DPCT_ORIG     unsigned int upper_limit_z = (unsigned int)floor(p.vec[2]+half_W);*/
    unsigned int upper_limit_z = (unsigned int)sycl::floor(p.vec[2] + half_W);

    unsigned int pair_idx = 0;
    unsigned int write_offset = (sample_idx==0) ? 0 : write_offsets[sample_idx-1];
    unsigned int frame_offset = frame*prod(matrix_size_os+matrix_size_wrap);
    for( unsigned int z=lower_limit_z; z<=upper_limit_z; z++ ){
        for( unsigned int y=lower_limit_y; y<=upper_limit_y; y++ ){
            for( unsigned int x=lower_limit_x; x<=upper_limit_x; x++ ){
                typename uintd<3>::Type co; co.vec[0] = x; co.vec[1] = y; co.vec[2] = z;
                tuples_first[write_offset+pair_idx] = co_to_idx(co, matrix_size_os+matrix_size_wrap)+frame_offset;
                tuples_last[write_offset+pair_idx] = sample_idx;
                pair_idx++;
            }
        }
    }
}

/* DPCT_ORIG template <class REAL> __inline__ __device__ void
output_pairs( unsigned int sample_idx, unsigned int frame,
              typename reald<REAL,4>::Type &p, typename uintd<4>::Type &matrix_size_os, typename uintd<4>::Type
&matrix_size_wrap, REAL half_W, const unsigned int * __restrict__ write_offsets, unsigned int * __restrict__
tuples_first, unsigned int * __restrict__ tuples_last )*/
template <class REAL>
__inline__ void output_pairs(unsigned int sample_idx, unsigned int frame, typename reald<REAL, 4>::Type& p,
                             typename uintd<4>::Type& matrix_size_os, typename uintd<4>::Type& matrix_size_wrap,
                             REAL half_W, const unsigned int* __restrict__ write_offsets,
                             unsigned int* __restrict__ tuples_first, unsigned int* __restrict__ tuples_last)
{
/* DPCT_ORIG     unsigned int lower_limit_x = (unsigned int)ceil(p.vec[0]-half_W);*/
    unsigned int lower_limit_x = (unsigned int)sycl::ceil(p.vec[0] - half_W);
/* DPCT_ORIG     unsigned int lower_limit_y = (unsigned int)ceil(p.vec[1]-half_W);*/
    unsigned int lower_limit_y = (unsigned int)sycl::ceil(p.vec[1] - half_W);
/* DPCT_ORIG     unsigned int lower_limit_z = (unsigned int)ceil(p.vec[2]-half_W);*/
    unsigned int lower_limit_z = (unsigned int)sycl::ceil(p.vec[2] - half_W);
/* DPCT_ORIG     unsigned int lower_limit_w = (unsigned int)ceil(p.vec[3]-half_W);*/
    unsigned int lower_limit_w = (unsigned int)sycl::ceil(p.vec[3] - half_W);
/* DPCT_ORIG     unsigned int upper_limit_x = (unsigned int)floor(p.vec[0]+half_W);*/
    unsigned int upper_limit_x = (unsigned int)sycl::floor(p.vec[0] + half_W);
/* DPCT_ORIG     unsigned int upper_limit_y = (unsigned int)floor(p.vec[1]+half_W);*/
    unsigned int upper_limit_y = (unsigned int)sycl::floor(p.vec[1] + half_W);
/* DPCT_ORIG     unsigned int upper_limit_z = (unsigned int)floor(p.vec[2]+half_W);*/
    unsigned int upper_limit_z = (unsigned int)sycl::floor(p.vec[2] + half_W);
/* DPCT_ORIG     unsigned int upper_limit_w = (unsigned int)floor(p.vec[3]+half_W);*/
    unsigned int upper_limit_w = (unsigned int)sycl::floor(p.vec[3] + half_W);

    unsigned int pair_idx = 0;
    unsigned int write_offset = (sample_idx==0) ? 0 : write_offsets[sample_idx-1];
    unsigned int frame_offset = frame*prod(matrix_size_os+matrix_size_wrap);
    for( unsigned int w=lower_limit_w; w<=upper_limit_w; w++ ){
        for( unsigned int z=lower_limit_z; z<=upper_limit_z; z++ ){
            for( unsigned int y=lower_limit_y; y<=upper_limit_y; y++ ){
	            for( unsigned int x=lower_limit_x; x<=upper_limit_x; x++ ){
                    typename uintd<4>::Type co; co.vec[0] = x; co.vec[1] = y; co.vec[2] = z; co.vec[3] = w;
                    tuples_first[write_offset+pair_idx] = co_to_idx(co, matrix_size_os+matrix_size_wrap)+frame_offset;
                    tuples_last[write_offset+pair_idx] = sample_idx;
                    pair_idx++;
	            }
            }
        }
    }
}

/* DPCT_ORIG template<class REAL, unsigned int D> __global__ void
write_pairs_kernel( typename uintd<D>::Type matrix_size_os, typename uintd<D>::Type matrix_size_wrap, unsigned int
num_samples_per_frame, REAL half_W, const typename reald<REAL,D>::Type * __restrict__ traj_positions, unsigned int *
__restrict__ write_offsets, unsigned int * __restrict__ tuples_first, unsigned int * __restrict__ tuples_last )*/
template <class REAL, unsigned int D>
void write_pairs_kernel(typename uintd<D>::Type matrix_size_os, typename uintd<D>::Type matrix_size_wrap,
                        unsigned int num_samples_per_frame, REAL half_W,
                        const typename reald<REAL, D>::Type* __restrict__ traj_positions,
                        unsigned int* __restrict__ write_offsets, unsigned int* __restrict__ tuples_first,
                        unsigned int* __restrict__ tuples_last)
{
    // Get sample idx
/* DPCT_ORIG     unsigned int sample_idx = blockIdx.x*blockDim.x + threadIdx.x;*/
    auto item_ct1 = sycl::ext::oneapi::this_work_item::get_nd_item<3>();
    unsigned int sample_idx = item_ct1.get_group(2) * item_ct1.get_local_range(2) + item_ct1.get_local_id(2);
/* DPCT_ORIG     unsigned int frame = blockIdx.y;*/
    unsigned int frame = item_ct1.get_group(1);

    if( sample_idx<num_samples_per_frame ){

        sample_idx += frame*num_samples_per_frame;
        typename reald<REAL,D>::Type p = traj_positions[sample_idx];
        output_pairs<REAL>( sample_idx, frame, p, matrix_size_os, matrix_size_wrap, half_W, write_offsets, tuples_first, tuples_last );
    }
};

template <class REAL, unsigned int D> void 
write_pairs( typename uintd<D>::Type matrix_size_os, typename uintd<D>::Type matrix_size_wrap, unsigned int num_samples_per_frame, unsigned int num_frames, REAL W, 
	     const typename reald<REAL,D>::Type * __restrict__ traj_positions, unsigned int * __restrict__ write_offsets, unsigned int * __restrict__ tuples_first, unsigned int * __restrict__ tuples_last )
{
/* DPCT_ORIG     dim3 blockDim(256);*/
    dpct::dim3 blockDim(256);
/* DPCT_ORIG     dim3 gridDim((int)ceil((double)num_samples_per_frame/(double)blockDim.x), num_frames);*/
    dpct::dim3 gridDim((int)ceil((double)num_samples_per_frame / (double)blockDim.x), num_frames);

    REAL half_W = REAL(0.5)*W;
/* DPCT_ORIG     write_pairs_kernel<REAL,D><<< gridDim, blockDim >>>
        ( matrix_size_os, matrix_size_wrap, num_samples_per_frame, half_W, traj_positions, write_offsets, tuples_first,
   tuples_last );*/
    /*
    DPCT1049:5: The work-group size passed to the SYCL kernel may exceed the limit. To get the device limit, query
    info::device::max_work_group_size. Adjust the work-group size if needed.
    */
      {
            auto exp_props =
                sycl::ext::oneapi::experimental::properties{sycl::ext::oneapi::experimental::use_root_sync};
            dpct::has_capability_or_fail(dpct::get_in_order_queue().get_device(), {sycl::aspect::fp64});

            dpct::get_in_order_queue().submit([&](sycl::handler& cgh) {
                  cgh.depends_on(dpct::get_current_device().get_in_order_queues_last_events());

                  cgh.parallel_for<dpct_kernel_name<class write_pairs_kernel_e67b2a, REAL, dpct_kernel_scalar<D>>>(
                      sycl::nd_range<3>(gridDim * blockDim, blockDim), exp_props, [=](sycl::nd_item<3> item_ct1) {
                            write_pairs_kernel<REAL, D>(matrix_size_os, matrix_size_wrap, num_samples_per_frame, half_W,
                                                        traj_positions, write_offsets, tuples_first, tuples_last);
                      });
            });
      }

    CHECK_FOR_CUDA_ERROR();
}


