    template <typename T> void fft1(hoNDArray<std::complex<T>>& a, bool forward) {
        hoNDArray<std::complex<T>> res(a);
        fft1(res, a, forward);
    }

    template <typename T> void fft2(hoNDArray<std::complex<T>>& a, bool forward) {
        hoNDArray<std::complex<T>> res(a);
        fft2(res, a, forward);
    }

